#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/claude-cli/tasks/upgrade-ai.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Setup / Upgrade AI tools"
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

import json
import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def run(*cmd):
  """Run the command. When it fails, stop the task with its code, as set -e
  does. A missing command gives 127, as in the shell."""
  sys.stdout.flush()
  try:
    rc = subprocess.run(cmd, check=False).returncode
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    sys.exit(127)
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def read_json(*cmd):
  """Run the command and return its stdout as JSON. A failure of the command
  or an output that is not JSON gives None: the shell ignored the code of
  the command before the jq pipe too."""
  sys.stdout.flush()
  try:
    out = subprocess.run(cmd, check=False, stdout=subprocess.PIPE).stdout
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    return None
  try:
    return json.loads(out)
  except ValueError:
    return None


def has_marketplace(name):
  """True when claude lists the marketplace name."""
  data = read_json("claude", "plugins", "marketplace", "list", "--json")
  return isinstance(data, list) and any(isinstance(m, dict) and m.get("name") == name for m in data)


def main():
  helpers.print_header("Upgrading AI tools ...")

  helpers.print_subheader("Adding marketplaces ...")
  if not has_marketplace("claude-plugins-official"):
    run("claude", "plugins", "marketplace", "add", "anthropics/claude-plugins-official")
  if not has_marketplace("virajp-plugins"):
    run("claude", "plugins", "marketplace", "add", "virajp/claude-plugins")

  helpers.print_subheader("Upgrading marketplaces ...")
  run("claude", "plugins", "marketplace", "update")

  helpers.print_subheader("Upgrading plugins ...")
  data = read_json("claude", "plugins", "list", "--json")
  plugins = data if isinstance(data, list) else []
  for plugin in plugins:
    if isinstance(plugin, dict) and plugin.get("scope") == "user" and isinstance(plugin.get("id"), str):
      run("claude", "plugin", "update", plugin["id"], "--yes")

  helpers.print_subheader("Prune plugins ...")
  run("claude", "plugin", "autoremove", "--scope", "user", "--yes")


if __name__ == "__main__":
  main()
